let currentLanguage=localStorage.getItem('optimus-language')||'ar';
function applyLanguage(lang){
  currentLanguage=lang==='en'?'en':'ar';
  localStorage.setItem('optimus-language',currentLanguage);
  document.documentElement.lang=currentLanguage;
  document.documentElement.dir=currentLanguage==='ar'?'rtl':'ltr';
  document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(I18N[currentLanguage][key])el.textContent=I18N[currentLanguage][key]});
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{const key=el.dataset.i18nPlaceholder;if(I18N[currentLanguage][key])el.setAttribute('placeholder',I18N[currentLanguage][key]);});
  document.querySelectorAll('[data-role]').forEach(el=>{el.textContent=currentLanguage==='ar'?(el.dataset.role==='admin'?'مدير':'موظف'):(el.dataset.role==='admin'?'Admin':'Employee')});
  const toggle=document.getElementById('languageToggle');if(toggle)toggle.textContent=currentLanguage==='ar'?'EN':'AR';
  const weekdays=currentLanguage==='ar'?['أحد','إثنين','ثلاثاء','أربعاء','خميس','جمعة','سبت']:['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];document.querySelectorAll('[data-weekday]').forEach(el=>{el.textContent=weekdays[Number(el.dataset.weekday)||0]});
  document.querySelectorAll('select option[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(I18N[currentLanguage][key])el.textContent=I18N[currentLanguage][key]});
  updateGreeting();
  const greeting=document.getElementById('timeGreeting');
  if(greeting){const h=new Date().getHours();greeting.textContent=currentLanguage==='ar'?(h>=5&&h<12?'صباح الخير، أهلاً بك':'مساء الخير، أهلاً بك'):(h>=5&&h<12?'Good morning, welcome':'Good evening, welcome');}
}

function initHebronClock(){
  const timeEl=document.getElementById('hebronClockTime');
  const dateEl=document.getElementById('hebronClockDate');
  if(!timeEl||!dateEl)return;
  const update=()=>{
    const now=new Date();
    const locale=currentLanguage==='ar'?'ar-PS':'en-GB';
    timeEl.textContent=new Intl.DateTimeFormat(locale,{timeZone:'Asia/Hebron',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(now);
    dateEl.textContent=new Intl.DateTimeFormat(locale,{timeZone:'Asia/Hebron',weekday:'short',day:'2-digit',month:'short'}).format(now);
  };
  update();setInterval(update,1000);
}

function updateGreeting(){
  const el=document.getElementById('greetingTitle');if(!el)return;
  const name=el.dataset.name||'',morning=el.dataset.greeting==='morning';
  el.textContent=currentLanguage==='ar'?(morning?`صباح الخير، ${name}`:`مساء الخير، ${name}`):(morning?`Good morning, ${name}`:`Good evening, ${name}`);
}
document.addEventListener('DOMContentLoaded',()=>{
  document.documentElement.dataset.theme='dark';
  applyLanguage(currentLanguage);
  document.getElementById('languageToggle')?.addEventListener('click',()=>applyLanguage(currentLanguage==='ar'?'en':'ar'));
  const show=document.getElementById('showPassword');show?.addEventListener('click',()=>{const input=document.getElementById('passwordInput');input.type=input.type==='password'?'text':'password';});
});

window.initRangeCalendar=function(){
  const trigger=document.getElementById('rangeTrigger');
  if(!trigger)return;
  const modal=document.getElementById('calendarModal');
  const panel=modal?.querySelector('.calendar-panel');
  const grid=document.getElementById('calendarGrid');
  const title=document.getElementById('calendarMonth');
  const label=document.getElementById('rangeLabel');
  const startInput=document.getElementById('startDate');
  const endInput=document.getElementById('endDate');
  const startPreview=document.getElementById('calendarStartPreview');
  const endPreview=document.getElementById('calendarEndPreview');
  const hint=document.getElementById('calendarHint');
  let view=new Date(),start=null,end=null,monthDirection=1;
  const monthNames={ar:['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'],en:['January','February','March','April','May','June','July','August','September','October','November','December']};
  const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const same=(a,b)=>a&&b&&a.toDateString()===b.toDateString();
  const between=(d,a,b)=>a&&b&&d>=a&&d<=b;
  const locale=()=>currentLanguage==='ar'?'ar-EG':'en-GB';
  const pretty=d=>d?d.toLocaleDateString(locale(),{day:'2-digit',month:'short',year:'numeric'}):'—';
  function refreshPreview(){
    if(startPreview)startPreview.textContent=pretty(start);
    if(endPreview)endPreview.textContent=pretty(end);
    if(panel){
      panel.classList.toggle('has-start',!!start);
      panel.classList.toggle('has-range',!!start&&!!end);
    }
  }
  function animateGrid(){
    if(!grid)return;
    grid.classList.remove('calendar-slide-next','calendar-slide-prev');
    void grid.offsetWidth;
    grid.classList.add(monthDirection>0?'calendar-slide-next':'calendar-slide-prev');
  }
  function render(){
    title.textContent=`${monthNames[currentLanguage][view.getMonth()]} ${view.getFullYear()}`;
    grid.innerHTML='';
    const first=new Date(view.getFullYear(),view.getMonth(),1),offset=first.getDay(),days=new Date(view.getFullYear(),view.getMonth()+1,0).getDate();
    for(let i=0;i<offset;i++){const x=document.createElement('span');x.className='calendar-spacer';grid.appendChild(x)}
    for(let n=1;n<=days;n++){
      const d=new Date(view.getFullYear(),view.getMonth(),n);
      const b=document.createElement('button');
      b.type='button';b.className='calendar-day';b.textContent=n;
      if(same(d,new Date()))b.classList.add('today');
      if(same(d,start))b.classList.add('start');
      if(same(d,end))b.classList.add('end');
      if(start&&end&&between(d,start,end))b.classList.add('in-range');
      b.style.setProperty('--day-index',String(n));
      b.addEventListener('click',()=>{
        b.classList.add('day-picked');
        if(!start||end){start=d;end=null}
        else if(d<start){end=start;start=d}
        else{end=d}
        render();updateLabel();refreshPreview();
      });
      grid.appendChild(b)
    }
    refreshPreview();
  }
  function updateLabel(){
    if(start&&end)label.textContent=`${pretty(start)} ← ${pretty(end)}`;
    else if(start)label.textContent=currentLanguage==='ar'?`البداية: ${pretty(start)} — اختر النهاية`:`Start: ${pretty(start)} — choose the end`;
    else label.textContent=currentLanguage==='ar'?'لم يتم اختيار فترة':'No period selected';
  }
  function openModal(){
    modal.classList.remove('hidden');
    requestAnimationFrame(()=>modal.classList.add('calendar-open'));
    render();
  }
  function closeModal(){
    modal.classList.remove('calendar-open');
    setTimeout(()=>modal.classList.add('hidden'),180);
  }
  trigger.addEventListener('click',openModal);
  modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.classList.contains('hidden'))closeModal()});
  document.getElementById('prevMonth').onclick=()=>{monthDirection=-1;view=new Date(view.getFullYear(),view.getMonth()-1,1);animateGrid();render()};
  document.getElementById('nextMonth').onclick=()=>{monthDirection=1;view=new Date(view.getFullYear(),view.getMonth()+1,1);animateGrid();render()};
  document.getElementById('clearRange').onclick=()=>{start=end=null;startInput.value=endInput.value='';if(hint)hint.textContent=currentLanguage==='ar'?'اختر يوم البداية ثم يوم النهاية':'Choose the start day, then the end day';updateLabel();render()};
  document.getElementById('applyRange').onclick=()=>{
    if(!start||!end){if(hint){hint.textContent=currentLanguage==='ar'?'اختر يوم البداية ويوم النهاية أولاً':'Choose the start and end days first';hint.classList.add('calendar-warning');setTimeout(()=>hint.classList.remove('calendar-warning'),900)}return}
    startInput.value=iso(start);endInput.value=iso(end);trigger.classList.add('range-confirmed');setTimeout(()=>trigger.classList.remove('range-confirmed'),650);closeModal();
  };
  document.getElementById('reportForm').addEventListener('submit',e=>{if(!startInput.value||!endInput.value){e.preventDefault();openModal()}});
};

function formatDuration(totalSeconds){
  const seconds=Math.max(0,Number(totalSeconds)||0),minutes=Math.floor(seconds/60),rest=Math.floor(seconds%60);
  return `${String(minutes).padStart(2,'0')}:${String(rest).padStart(2,'0')}`;
}
function updateClock(totalSeconds){
  const seconds=Math.max(0,Number(totalSeconds)||0);
  const secondHand=document.getElementById('secondHand'),minuteHand=document.getElementById('minuteHand'),text=document.getElementById('elapsedText');
  if(secondHand)secondHand.style.transform=`translateX(-50%) rotate(${(seconds%60)*6}deg)`;
  if(minuteHand)minuteHand.style.transform=`translateX(-50%) rotate(${(seconds/60)*6}deg)`;
  if(text)text.textContent=formatDuration(seconds);
}
function pollJob(jobId,panel){
  const stage=panel.querySelector('#jobStage'),bar=panel.querySelector('#jobBar'),result=panel.querySelector('#jobResult'),cancelButton=panel.querySelector('#cancelReport');
  panel.classList.remove('hidden');
  localStorage.setItem('optimus-active-job',jobId);
  if(cancelButton){
    cancelButton.disabled=false;
    cancelButton.onclick=()=>{
      const modal=document.getElementById('cancelConfirmModal');
      if(modal){modal.classList.remove('hidden');modal.setAttribute('aria-hidden','false');}
    };
  }
  const cancelModal=document.getElementById('cancelConfirmModal');
  const cancelNo=document.getElementById('cancelConfirmNo');
  const cancelYes=document.getElementById('cancelConfirmYes');
  const closeCancelModal=()=>{if(cancelModal){cancelModal.classList.add('hidden');cancelModal.setAttribute('aria-hidden','true');}};
  cancelNo?.addEventListener('click',closeCancelModal);
  cancelModal?.addEventListener('click',(event)=>{if(event.target===cancelModal)closeCancelModal();});
  cancelYes?.addEventListener('click',async()=>{
    closeCancelModal();
    stopped=true;stopClock();localStorage.removeItem('optimus-active-job');
    if(cancelButton){cancelButton.disabled=true;cancelButton.classList.add('hidden');}
    if(stage)stage.textContent=I18N[currentLanguage].report_cancelled;
    if(result)result.innerHTML=`<div class="flash success">${I18N[currentLanguage].report_cancelled}</div>`;
    try{await fetch(`/api/jobs/${jobId}/cancel`,{method:'POST',cache:'no-store'});}catch(_error){}
  });
  let stopped=false;
  let jobStartedAtMs=null;
  let frozenElapsed=null;
  const liveClock=setInterval(()=>{
    if(stopped||jobStartedAtMs===null||frozenElapsed!==null)return;
    updateClock(Math.max(0,Math.floor((Date.now()-jobStartedAtMs)/1000)));
  },250);
  function stopClock(){clearInterval(liveClock);}
  function syncClock(serverElapsed,startedAtEpoch,freeze=false){
    const seconds=Math.max(0,Number(serverElapsed)||0);
    const epoch=Number(startedAtEpoch)||0;
    if(epoch>0)jobStartedAtMs=epoch*1000;else if(jobStartedAtMs===null)jobStartedAtMs=Date.now()-(seconds*1000);
    if(freeze)frozenElapsed=Math.floor(seconds);
    updateClock(freeze?frozenElapsed:Math.max(seconds,Math.floor((Date.now()-jobStartedAtMs)/1000)));
  }
  async function check(){
    if(stopped)return;
    try{
      const res=await fetch(`/api/jobs/${jobId}`,{cache:'no-store'}),data=await res.json();
      if(res.status===404||res.status===403){stopped=true;stopClock();localStorage.removeItem('optimus-active-job');panel.classList.add('hidden');return;}
      if(!res.ok)throw new Error(data.error||(currentLanguage==='ar'?'تعذر قراءة حالة التقرير':'Unable to read report status'));
      if(stage)stage.textContent=I18N[currentLanguage].please_wait;
      if(bar)bar.style.width=`${Math.max(4,data.progress||0)}%`;
      syncClock(data.elapsed_seconds,data.started_at_epoch);
      if(result&&data.status==='running')result.innerHTML='';
      if(data.status==='cancelling'){
        if(stage)stage.textContent=currentLanguage==='ar'?'جارٍ إيقاف التقرير':'Stopping report';
        if(cancelButton)cancelButton.disabled=true;
      }
      if(data.status==='completed'){
        stopped=true;stopClock();localStorage.removeItem('optimus-active-job');if(cancelButton)cancelButton.classList.add('hidden');
        syncClock(data.elapsed_seconds,data.started_at_epoch,true);
        if(stage)stage.textContent=currentLanguage==='ar'?'اكتمل التقرير':'Report complete';
        if(result)result.innerHTML=`<div class="job-success">${I18N[currentLanguage].completed_in} ${formatDuration(data.elapsed_seconds)}</div><a class="primary-button download-link" href="${data.download_url}">${I18N[currentLanguage].download_excel}</a>`;
        return;
      }
      if(data.status==='cancelled'){
        stopped=true;stopClock();localStorage.removeItem('optimus-active-job');if(cancelButton)cancelButton.classList.add('hidden');
        if(stage)stage.textContent=I18N[currentLanguage].report_cancelled;
        if(result)result.innerHTML=`<div class="flash error">${I18N[currentLanguage].report_cancelled}</div>`;
        return;
      }
      if(data.status==='failed'){
        stopped=true;stopClock();localStorage.removeItem('optimus-active-job');if(cancelButton)cancelButton.classList.add('hidden');
        if(stage)stage.textContent=I18N[currentLanguage].report_failed;
        const safeMessage=(data.error||I18N[currentLanguage].report_failed).replace(/[<>]/g,'');
        if(result)result.innerHTML=`<div class="flash error">${safeMessage}</div>`;
        return;
      }
    }catch(error){if(result)result.innerHTML=`<div class="flash error">${String(error.message||error).replace(/[<>]/g,'')}</div>`}
    setTimeout(check,1500);
  }
  check();
}
