// ===== 2.3.3: precise loading feedback without artificial delays =====
(function(){
  const overlay=()=>document.getElementById('globalLoadingOverlay');
  let safetyTimer=null;

  window.showGlobalLoading=function(options={}){
    const el=overlay(); if(!el)return;
    const persistent=Boolean(options.persistent);
    el.style.pointerEvents='auto';
    el.classList.add('visible');
    el.setAttribute('aria-hidden','false');
    document.documentElement.classList.add('is-global-loading');
    clearTimeout(safetyTimer);
    if(!persistent)safetyTimer=setTimeout(window.hideGlobalLoading,650);
  };

  window.hideGlobalLoading=function(){
    const el=overlay();
    clearTimeout(safetyTimer);
    if(el){
      el.classList.remove('visible');
      el.setAttribute('aria-hidden','true');
      el.style.pointerEvents='none';
    }
    document.documentElement.classList.remove('is-global-loading');
  };

  const isCalendarAction=(element)=>Boolean(
    element?.closest?.('#calendarModal,#rangeTrigger,.calendar-modal,.calendar-panel')
  );

  document.addEventListener('submit',function(event){
    const form=event.target;
    if(!(form instanceof HTMLFormElement))return;
    if(form.id==='reportForm'||form.matches('[data-no-global-loading]'))return;
    if(!form.checkValidity())return;
    window.showGlobalLoading({persistent:true});
  },true);

  document.addEventListener('click',function(event){
    const actionable=event.target.closest('a[href],button,[role="button"]');
    if(!actionable||actionable.matches('[data-no-global-loading]')||isCalendarAction(actionable))return;
    if(actionable instanceof HTMLAnchorElement){
      if(actionable.target==='_blank'||actionable.hasAttribute('download'))return;
      const href=actionable.getAttribute('href')||'';
      if(!href||href.startsWith('#')||href.startsWith('javascript:'))return;
      try{
        const url=new URL(actionable.href,location.href);
        if(url.origin!==location.origin)return;
      }catch(_error){return;}
      window.showGlobalLoading({persistent:true});
      return;
    }
    if(actionable instanceof HTMLButtonElement && actionable.type==='button'){
      window.showGlobalLoading({persistent:false});
    }
  },true);

  window.addEventListener('pageshow',window.hideGlobalLoading);
  window.addEventListener('DOMContentLoaded',window.hideGlobalLoading);
  window.addEventListener('load',window.hideGlobalLoading);
  window.addEventListener('focus',()=>setTimeout(window.hideGlobalLoading,0));
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)setTimeout(window.hideGlobalLoading,0);});
})();

