  if(!trigger||!modal)return;
  const panel=modal.querySelector('.calendar-panel'),grid=document.getElementById('transferCalendarGrid'),title=document.getElementById('transferCalendarMonth'),label=document.getElementById('transferRangeLabel');
  const startInput=document.getElementById('transferStartDate'),endInput=document.getElementById('transferEndDate'),startPreview=document.getElementById('transferStartPreview'),endPreview=document.getElementById('transferEndPreview'),hint=document.getElementById('transferCalendarHint');
  const source=document.getElementById('sourceManagerSelect'),target=document.getElementById('targetManagerSelect'),status=document.getElementById('managerLoadStatus'),refreshButton=document.getElementById('refreshManagersButton'),targetStep=document.getElementById('transferTargetStep');
  const direction=document.querySelector('.transfer-direction');
