  const searchForm=document.getElementById('managerTransferSearchForm'),searchState=document.getElementById('transferSearchState'),resultsTitle=document.getElementById('transferResultsTitle'),resultsBody=document.getElementById('transferResultsBody'),transferForm=document.getElementById('transferForm'),selectAllWrap=document.getElementById('selectAllTransferWrap'),selectAll=document.getElementById('selectAllTransfer'),localSearch=document.getElementById('transferLocalSearch'),selectedCount=document.getElementById('transferSelectedCount');
  const parseIso=value=>{if(!value)return null;const [y,m,d]=value.split('-').map(Number);return y&&m&&d?new Date(y,m-1,d):null};
