  function updateRange(){startPreview.textContent=pretty(start);endPreview.textContent=pretty(end);panel.classList.toggle('has-start',!!start);panel.classList.toggle('has-range',!!start&&!!end);label.textContent=start&&end?`${pretty(start)} ← ${pretty(end)}`:(start?(currentLanguage==='ar'?`البداية: ${pretty(start)} — اختر النهاية`:`Start: ${pretty(start)} — choose the end`):t('no_period_selected','لم يتم اختيار فترة'));}
  function renderCalendar(){title.textContent=`${monthNames[currentLanguage][view.getMonth()]} ${view.getFullYear()}`;grid.innerHTML='';const first=new Date(view.getFullYear(),view.getMonth(),1),offset=first.getDay(),days=new Date(view.getFullYear(),view.getMonth()+1,0).getDate();for(let i=0;i<offset;i++){const x=document.createElement('span');x.className='calendar-spacer';grid.appendChild(x)}for(let n=1;n<=days;n++){const d=new Date(view.getFullYear(),view.getMonth(),n),b=document.createElement('button');b.type='button';b.className='calendar-day';b.textContent=n;b.dataset.noGlobalLoading='1';if(same(d,new Date()))b.classList.add('today');if(same(d,start))b.classList.add('start');if(same(d,end))b.classList.add('end');if(start&&end&&between(d,start,end))b.classList.add('in-range');b.onclick=()=>{if(!start||end){start=d;end=null}else if(d<start){end=start;start=d}else end=d;renderCalendar();updateRange()};grid.appendChild(b)}updateRange();}
