window.initDownloadCenter=function(){
  const search=document.getElementById('downloadSearch'),list=document.getElementById('downloadList'),count=document.getElementById('visibleFileCount');if(!list)return;
  let filter='all';
  const apply=()=>{const term=(search?.value||'').trim().toLowerCase();let visible=0;list.querySelectorAll('.download-item').forEach(item=>{const show=(filter==='all'||item.dataset.type===filter)&&(!term||item.dataset.name.includes(term));item.hidden=!show;if(show)visible++});if(count)count.textContent=visible};
  search?.addEventListener('input',apply);document.querySelectorAll('.filter-chip').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.filter-chip').forEach(x=>x.classList.remove('active'));button.classList.add('active');filter=button.dataset.filter||'all';apply()}));
};
